{"path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","command":"create","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  max_attempts: number;
  progress: Record<string, unknown>;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  available_at: Date;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {
  attemptToken: string;
}

export function toPublicErasureRequest(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findCustomer(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async findCustomerIncludingErased(merchantId: string, customerId: string): Promise<boolean> {
    const existing = await this.findCustomer(merchantId, customerId);
    if (existing) return true;
    const tombstone = await pool.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(tombstone.rowCount);
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async createOrResume(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow> {
    const existing = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests
       WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    if (existing.rows[0]) {
      const row = existing.rows[0];
      if (row.status === 'failed') {
        const resumed = await client.query<ErasureRequestRow>(
          `UPDATE customers.erasure_requests
           SET status='pending', available_at=now(), updated_at=now(),
               locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error=NULL
           WHERE id=$1
           RETURNING *`,
          [row.id],
        );
        return resumed.rows[0]!;
      }
      return row;
    }

    const created = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status)
       VALUES($1,$2,'pending')
       ON CONFLICT (merchant_id, customer_id) DO UPDATE
       SET updated_at=customers.erasure_requests.updated_at
       RETURNING *`,
      [merchantId, customerId],
    );
    return created.rows[0]!;
  }

  async claim(workerId: string, leaseSeconds = 120): Promise<ClaimedErasureRequest | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
           lease_expires_at=now()+($2 || ' seconds')::interval, updated_at=now(), last_error=NULL
       WHERE id=(
         SELECT id FROM customers.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now()
         ORDER BY available_at, created_at
         FOR UPDATE SKIP LOCKED LIMIT 1
       )
       RETURNING *`,
      [workerId, leaseSeconds],
    );
    const row = result.rows[0];
    if (!row) return undefined;
    return { ...row, attemptToken: workerId };
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=COALESCE(last_error,'worker_lease_expired'), updated_at=now()
       WHERE status='processing' AND lease_expires_at < now()`,
    );
    return result.rowCount ?? 0;
  }

  async markStep(
    client: pg.PoolClient,
    requestId: string,
    step: string,
    detail: Record<string, unknown> = {},
  ): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET progress = progress || jsonb_build_object($2::text, $3::jsonb), updated_at=now()
       WHERE id=$1`,
      [requestId, step, JSON.stringify({ completedAt: new Date().toISOString(), ...detail })],
    );
  }

  async complete(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), updated_at=now(), last_error=NULL,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE id=$1`,
      [request.id],
    );
    await client.query(
      `INSERT INTO customers.erasure_tombstones(customer_id,merchant_id,erasure_request_id)
       VALUES($1,$2,$3) ON CONFLICT(customer_id) DO NOTHING`,
      [request.customer_id, request.merchant_id, request.id],
    );
  }

  async fail(request: ClaimedErasureRequest, error: unknown): Promise<void> {
    const message = error instanceof Error ? error.message.slice(0, 200) : String(error).slice(0, 200);
    const code = stableErrorCode(message);
    if (request.attempts >= request.max_attempts) {
      await pool.query(
        `UPDATE customers.erasure_requests
         SET status='failed', last_error=$2, updated_at=now(),
             locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
             available_at=now()+interval '1 hour'
         WHERE id=$1`,
        [request.id, code],
      );
      return;
    }
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2, updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           available_at=now()+(($3 || ' seconds')::interval)
       WHERE id=$1`,
      [request.id, code, Math.min(300, 2 ** Math.min(request.attempts, 8))],
    );
  }
}

function stableErrorCode(message: string): string {
  const normalized = message.toLowerCase();
  if (normalized.includes('opensearch')) return 'search_cleanup_failed';
  if (normalized.includes('redis')) return 'cache_cleanup_failed';
  if (normalized.includes('minio') || normalized.includes('object') || normalized.includes('s3')) {
    return 'document_cleanup_failed';
  }
  if (normalized.includes('provider')) return 'provider_cleanup_failed';
  if (normalized.includes('mail') || normalized.includes('email')) return 'notification_cleanup_failed';
  if (normalized.includes('timeout') || normalized.includes('econn')) return 'transient_dependency_failure';
  return 'erasure_step_failed';
}

export async function isCustomerErased(customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM customers.erasure_tombstones WHERE customer_id=$1`,
    [customerId],
  );
  return Boolean(result.rowCount);
}

export async function isCustomerErasedTx(client: pg.PoolClient, customerId: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.erasure_tombstones WHERE customer_id=$1`,
    [customerId],
  );
  return Boolean(result.rowCount);
}
