{"path":"/workspace/source/apps/customer-service/src/erasure-service.ts","command":"create","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import type pg from 'pg';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  completeIdempotency,
  requestHash,
  reserveIdempotency,
} from '../../payment-service/src/idempotency.js';
import {
  ErasureRepository,
  toPublicErasureRequest,
  type ClaimedErasureRequest,
  type ErasureRequestRow,
} from './erasure-repository.js';

const ERASED_EMAIL = 'erased@deleted.invalid';
const ERASED_NAME = 'Erased Customer';
const ERASED_PHONE = null;
const ERASED_REFERENCE_PREFIX = 'erased-';
const REDACTED_TEXT = '[redacted]';

const ANONYMIZED_SNAPSHOT = {
  id: null,
  email: ERASED_EMAIL,
  name: ERASED_NAME,
  phone: ERASED_PHONE,
  external_reference: 'erased',
  status: 'erased',
};

export class ErasureService {
  private readonly repository = new ErasureRepository();
  private redis: Redis | undefined;

  private getRedis(): Redis {
    this.redis ??= new Redis(config().REDIS_URL, { maxRetriesPerRequest: 2, enableReadyCheck: false });
    return this.redis;
  }

  async createRequest(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: Record<string, unknown> }> {
    const customerKnown = await this.repository.findCustomerIncludingErased(merchantId, customerId);
    if (!customerKnown) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }

    const hash = requestHash({ customerId });
    return transaction(async (client) => {
      const replay = await reserveIdempotency(client, merchantId, 'customer-erasure', idempotencyKey, hash);
      if (replay) {
        return { status: replay.status, body: replay.body as Record<string, unknown> };
      }

      const row = await this.repository.createOrResume(client, merchantId, customerId);
      const body = toPublicErasureRequest(row);
      await completeIdempotency(client, merchantId, 'customer-erasure', idempotencyKey, 202, body);
      return { status: 202, body };
    });
  }

  async getRequest(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? toPublicErasureRequest(row) : undefined;
  }

  async processNext(workerId: string): Promise<boolean> {
    const request = await this.repository.claim(workerId);
    if (!request) return false;
    try {
      await this.execute(request);
      return true;
    } catch (error) {
      logger.error({ error, requestId: request.id }, 'erasure request failed');
      await this.repository.fail(request, error);
      return true;
    }
  }

  async recoverExpiredLeases(): Promise<number> {
    return this.repository.recoverExpiredLeases();
  }

  private async execute(request: ClaimedErasureRequest): Promise<void> {
    const progress = request.progress ?? {};

    if (!progress.core_customer) {
      await transaction(async (client) => {
        await this.scrubCoreCustomer(client, request);
        await this.repository.markStep(client, request.id, 'core_customer');
      });
    }

    if (!progress.payments) {
      await transaction(async (client) => {
        await this.scrubPayments(client, request);
        await this.repository.markStep(client, request.id, 'payments');
      });
    }

    if (!progress.notifications) {
      await transaction(async (client) => {
        await this.scrubNotifications(client, request);
        await this.repository.markStep(client, request.id, 'notifications');
      });
    }

    if (!progress.analytics) {
      await transaction(async (client) => {
        await this.scrubAnalytics(client, request);
        await this.repository.markStep(client, request.id, 'analytics');
      });
    }

    if (!progress.outbox) {
      await transaction(async (client) => {
        await this.scrubOutboxAndJobs(client, request);
        await this.repository.markStep(client, request.id, 'outbox');
      });
    }

    if (!progress.provider) {
      await transaction(async (client) => {
        await this.scrubProvider(client, request);
        await this.repository.markStep(client, request.id, 'provider');
      });
    }

    if (!progress.documents) {
      await this.scrubDocuments(request);
      await transaction(async (client) => {
        await this.repository.markStep(client, request.id, 'documents');
      });
    }

    if (!progress.search_cache) {
      await this.scrubSearchAndCache(request);
      await transaction(async (client) => {
        await this.repository.markStep(client, request.id, 'search_cache');
      });
    }

    if (!progress.audit) {
      await transaction(async (client) => {
        await this.scrubAuditLogs(client, request);
        await this.repository.markStep(client, request.id, 'audit');
      });
    }

    await transaction(async (client) => {
      await this.repository.complete(client, request);
      await client.query(
        `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'system','erasure_request',$2,'customer.erasure.completed',$3,$4)`,
        [request.merchant_id, request.id, { customerId: request.customer_id }, randomUUID()],
      );
    });
  }

  private async scrubCoreCustomer(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    const erasedReference = `${ERASED_REFERENCE_PREFIX}${request.customer_id.replaceAll('-', '').slice(0, 24)}`;
    const erasedEmail = `erased+${request.customer_id.replaceAll('-', '')}@deleted.invalid`;

    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=$5, external_reference=$6, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [request.merchant_id, request.customer_id, erasedEmail, ERASED_NAME, ERASED_PHONE, erasedReference],
    );

    await client.query(
      `UPDATE customers.addresses
       SET line1=$3, line2=NULL, city=$3, region=NULL, postal_code=$3, country='XX'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, REDACTED_TEXT],
    );

    await client.query(
      `UPDATE customers.contacts SET value=$3 WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, REDACTED_TEXT],
    );

    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token=$3, brand=NULL, last4=NULL, billing_name=$4, billing_address=NULL, status='erased'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, `erased_${request.customer_id}`, REDACTED_TEXT],
    );

    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id],
    );

    await client.query(
      `UPDATE customers.support_messages
       SET body=$3, attachments='[]'::jsonb
       WHERE merchant_id=$1 AND author_type='customer' AND author_id=$2`,
      [request.merchant_id, request.customer_id, REDACTED_TEXT],
    );

    // Support tickets that only involve this customer get subject redacted; shared tickets keep subject
    // but participant linkage is retained without PII in message bodies already scrubbed above.
    await client.query(
      `UPDATE customers.support_tickets t
       SET subject=$3
       WHERE t.merchant_id=$1
         AND EXISTS (
           SELECT 1 FROM customers.support_participants sp
           WHERE sp.ticket_id=t.id AND sp.customer_id=$2
         )
         AND NOT EXISTS (
           SELECT 1 FROM customers.support_participants sp2
           WHERE sp2.ticket_id=t.id AND sp2.customer_id<>$2
         )`,
      [request.merchant_id, request.customer_id, REDACTED_TEXT],
    );

    // Drop import artifacts that contain the customer's raw record.
    const imports = await client.query<{ id: string; object_key: string }>(
      `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [request.merchant_id],
    );
    for (const row of imports.rows) {
      // Imports are merchant-scoped bulk files; we only clear ones whose object key embeds this customer id.
      if (row.object_key.includes(request.customer_id)) {
        await client.query(`DELETE FROM customers.customer_imports WHERE id=$1`, [row.id]);
      }
    }
  }

  private async scrubPayments(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    const snapshot = {
      ...ANONYMIZED_SNAPSHOT,
      id: request.customer_id,
      external_reference: `erased-${request.customer_id.slice(0, 8)}`,
    };

    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=$3::jsonb, description=CASE
         WHEN description IS NULL THEN NULL ELSE $4 END, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, JSON.stringify(snapshot), REDACTED_TEXT],
    );

    await client.query(
      `UPDATE payments.payment_attempts a
       SET request_payload = a.request_payload - 'customerEmail' - 'email' - 'name' - 'phone',
           response_payload = CASE
             WHEN a.response_payload IS NULL THEN NULL
             ELSE a.response_payload - 'customerEmail' - 'email' - 'name' - 'phone'
           END
       FROM payments.payment_intents p
       WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [request.merchant_id, request.customer_id],
    );

    await client.query(
      `UPDATE payments.refunds r
       SET customer_email=$3
       FROM payments.payment_intents p
       WHERE r.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [request.merchant_id, request.customer_id, ERASED_EMAIL],
    );

    await client.query(
      `UPDATE payments.disputes d
       SET evidence = CASE
         WHEN d.evidence IS NULL THEN '{}'::jsonb
         ELSE d.evidence - 'customerEmail' - 'email' - 'name' - 'phone' - 'billingAddress'
       END
       FROM payments.payment_intents p
       WHERE d.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [request.merchant_id, request.customer_id],
    );

    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=$3::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, JSON.stringify(snapshot)],
    );
  }

  private async scrubNotifications(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id],
    );

    await client.query(
      `UPDATE operations.email_deliveries
       SET destination=$3, subject=$4, text_body=$4, html_body=$4,
           status=CASE WHEN status IN ('pending','failed','processing') THEN 'cancelled' ELSE status END,
           cancelled_at=CASE WHEN status IN ('pending','failed','processing') THEN now() ELSE cancelled_at END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, ERASED_EMAIL, REDACTED_TEXT],
    );

    await client.query(
      `UPDATE operations.notifications
       SET destination=$3, payload='{}'::jsonb,
           status=CASE WHEN status IN ('queued','retrying','pending') THEN 'cancelled' ELSE status END,
           updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, ERASED_EMAIL],
    );
  }

  private async scrubAnalytics(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, anonymous_id=$3, properties='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id, `erased_${request.customer_id}`],
    );
  }

  private async scrubOutboxAndJobs(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    // Pending outbox events that still carry PII for this customer must not publish.
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = jsonb_strip_nulls(
             (payload - 'email' - 'customerEmail' - 'name' - 'phone' - 'billingName' - 'body' - 'subject')
             || jsonb_build_object(
               'email', $3::text,
               'customerEmail', $3::text,
               'name', $4::text,
               'erased', true
             )
           ),
           status=CASE WHEN status IN ('pending','publishing') THEN 'published' ELSE status END,
           published_at=COALESCE(published_at, now()),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE merchant_id=$1
         AND (
           aggregate_id=$2
           OR payload->>'customerId'=$2::text
           OR (payload->'customer'->>'id')=$2::text
         )`,
      [request.merchant_id, request.customer_id, ERASED_EMAIL, ERASED_NAME],
    );

    // Cancel pending document/receipt jobs that would re-materialize PII.
    await client.query(
      `UPDATE operations.jobs
       SET status='completed', locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           payload = payload || jsonb_build_object('customerSnapshot', $3::jsonb, 'erased', true),
           last_error='cancelled_by_erasure'
       WHERE merchant_id=$1
         AND status IN ('pending','retry','processing')
         AND (
           payload->>'customerId'=$2::text
           OR (payload->'customerSnapshot'->>'id')=$2::text
         )`,
      [request.merchant_id, request.customer_id, JSON.stringify(ANONYMIZED_SNAPSHOT)],
    );

    // Scrub dead letters that still hold customer payloads.
    await client.query(
      `UPDATE operations.dead_letters
       SET payload = CASE
         WHEN jsonb_typeof(payload)='object' THEN
           (payload - 'email' - 'customerEmail' - 'name' - 'phone' - 'body')
           || jsonb_build_object('erased', true)
         ELSE payload
       END
       WHERE (payload->>'customerId')=$1::text
          OR (payload->'customerSnapshot'->>'id')=$1::text`,
      [request.customer_id],
    );
  }

  private async scrubProvider(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email=$3, name=$4, external_reference=$5, updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [
        request.merchant_id,
        request.customer_id,
        ERASED_EMAIL,
        ERASED_NAME,
        `erased-${request.customer_id.slice(0, 8)}`,
      ],
    );
  }

  private async scrubDocuments(request: ClaimedErasureRequest): Promise<void> {
    const manifests = await pool.query<{ id: string; object_key: string; document_type: string; metadata: Record<string, unknown> }>(
      `SELECT id, object_key, document_type, metadata
       FROM operations.document_manifests
       WHERE merchant_id=$1 AND (customer_id=$2 OR object_key LIKE $3)`,
      [request.merchant_id, request.customer_id, `%${request.customer_id}%`],
    );

    for (const manifest of manifests.rows) {
      const anonymized = JSON.stringify({
        documentType: manifest.document_type,
        status: 'erased',
        erasedAt: new Date().toISOString(),
        metadata: { ...(manifest.metadata ?? {}), customerId: request.customer_id, erased: true },
      });
      try {
        await objectStore.putObject(
          DOCUMENT_BUCKET,
          manifest.object_key,
          anonymized,
          Buffer.byteLength(anonymized),
          { 'Content-Type': 'application/json' },
        );
      } catch (error) {
        // Object may already be gone; continue scrubbing remaining manifests.
        logger.warn({ error, objectKey: manifest.object_key }, 'document object replace failed');
      }
      const checksum = createHash('sha256').update(anonymized).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests
         SET customer_id=NULL, checksum=$2,
             metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('erased', true, 'erasedAt', $3::text)
         WHERE id=$1`,
        [manifest.id, checksum, new Date().toISOString()],
      );
    }

    // Customer import objects that are not linked via customer_id on the manifest.
    const imports = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND document_type='customer_import'`,
      [request.merchant_id],
    );
    for (const row of imports.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, row.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        const body = Buffer.concat(chunks).toString('utf8');
        if (!body.includes(request.customer_id)) continue;
        let parsed: Record<string, unknown> = {};
        try { parsed = JSON.parse(body) as Record<string, unknown>; } catch { parsed = {}; }
        const redacted = JSON.stringify({
          ...parsed,
          email: ERASED_EMAIL,
          name: ERASED_NAME,
          phone: null,
          notes: REDACTED_TEXT,
          erased: true,
        });
        await objectStore.putObject(DOCUMENT_BUCKET, row.object_key, redacted, Buffer.byteLength(redacted), {
          'Content-Type': 'application/json',
        });
        await pool.query(
          `UPDATE operations.document_manifests
           SET checksum=$2, metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('erased', true)
           WHERE object_key=$1`,
          [row.object_key, createHash('sha256').update(redacted).digest('hex')],
        );
      } catch (error) {
        logger.warn({ error, objectKey: row.object_key }, 'import object scrub failed');
      }
    }
  }

  private async scrubSearchAndCache(request: ClaimedErasureRequest): Promise<void> {
    const documentId = `${request.merchant_id}:${request.customer_id}`;
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: documentId, refresh: true });
    } catch (error) {
      const statusCode = (error as { meta?: { statusCode?: number } })?.meta?.statusCode;
      if (statusCode !== 404) throw error;
    }

    // Also remove by query in case alternate document ids were used.
    try {
      await searchClient.deleteByQuery({
        index: CUSTOMER_INDEX,
        body: {
          query: {
            bool: {
              must: [
                { term: { merchantId: request.merchant_id } },
                { term: { customerId: request.customer_id } },
              ],
            },
          },
        },
        refresh: true,
      });
    } catch (error) {
      const statusCode = (error as { meta?: { statusCode?: number } })?.meta?.statusCode;
      if (statusCode !== 404) throw error;
    }

    const redis = this.getRedis();
    const cacheKey = `merchant:${request.merchant_id}:customer:${request.customer_id}`;
    await redis.del(cacheKey, `${cacheKey}:activity`);
  }

  private async scrubAuditLogs(client: pg.PoolClient, request: ClaimedErasureRequest): Promise<void> {
    await client.query(
      `UPDATE platform.audit_logs
       SET metadata = CASE
         WHEN jsonb_typeof(metadata)='object' THEN
           (metadata - 'email' - 'phone' - 'name' - 'body' - 'value' - 'line1' - 'line2'
                     - 'city' - 'region' - 'postalCode' - 'billingName' - 'billingAddress')
           || jsonb_build_object('erased', true)
         ELSE metadata
       END
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2::text`,
      [request.merchant_id, request.customer_id],
    );
  }
}

export function isStepComplete(row: ErasureRequestRow, step: string): boolean {
  return Boolean(row.progress?.[step]);
}
"}

