export async function isCustomerErasedTx(client: pg.PoolClient, customerId: string): Promise<boolean> {
  const result = await client.query(
    `SELECT 1 FROM customers.erasure_tombstones WHERE customer_id=$1`,
    [customerId],
  );
  return Boolean(result.rowCount);
}

export const ERASED_EMAIL = 'erased@deleted.invalid';
export const ERASED_NAME = 'Erased Customer';

/** Strip personal fields from an event payload when the customer has been erased. */
export function redactPayloadForErasedCustomer(
  payload: Record<string, unknown>,
): Record<string, unknown> {
  const next: Record<string, unknown> = { ...payload, erased: true };
  for (const key of ['email', 'customerEmail', 'name', 'phone', 'billingName', 'body', 'subject']) {
    if (key in next) {
      if (key === 'email' || key === 'customerEmail') next[key] = ERASED_EMAIL;
      else if (key === 'name' || key === 'billingName') next[key] = ERASED_NAME;
      else next[key] = '[redacted]';
    }
  }
  if (next.customerSnapshot && typeof next.customerSnapshot === 'object') {
    next.customerSnapshot = {
      ...(next.customerSnapshot as Record<string, unknown>),
      email: ERASED_EMAIL,
      name: ERASED_NAME,
      phone: null,
    };
  }
  return next;
}
"}

